import React, { useCallback, memo } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';

const ActionButton = memo(({ button, index }) => {
  const navigate = useNavigate();
  
  const handleClick = useCallback(() => {
    // Execute the primary action
    if (button.onClick) {
      button.onClick();
    }
    
    // Navigate if a route is specified
    if (button.route) {
      setTimeout(() => {
        navigate(button.route);
      }, 100); // Small delay for better UX
    }
  }, [button, navigate]);
  
  return (
    <motion.button
      key={button.label}
      className={`px-3 py-2 ${button.color} ${button.hoverColor} text-white rounded-xl shadow-lg ${button.glowColor} flex items-center justify-center backdrop-blur-sm border border-white/10 text-sm relative overflow-hidden group`}
      whileHover={{ 
        scale: 1.03,
        transition: { duration: 0.2 }
      }}
      whileTap={{ 
        scale: 0.97,
        opacity: 0.9,
        transition: { duration: 0.1 }
      }}
      initial={{ opacity: 0, y: 20 }}
      animate={{ 
        opacity: 1, 
        y: 0,
        transition: { delay: 0.05 * index, duration: 0.3 }
      }}
      onClick={handleClick}
      role="button"
      aria-label={button.label}
    >
      {/* Animated gradient background */}
      <motion.div
        className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/10 to-white/0"
        animate={{
          x: ['-100%', '100%'],
        }}
        transition={{
          duration: 2,
          repeat: Infinity,
          repeatType: "loop",
          ease: "linear"
        }}
      />
      
      {/* Button content */}
      <div className="relative z-10 flex items-center">
        {button.icon}
        {button.label}
      </div>
    </motion.button>
  );
});

ActionButton.displayName = 'ActionButton';

const ActionPanel = memo(({ addNotification, theme, itemVariants }) => {
  const buttons = React.useMemo(() => [
    {
      label: 'Start Study Session',
      onClick: () => addNotification('Starting a new study session!', 'success'),
      route: '/pomodoro',
      icon: (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      ),
      color: 'bg-gradient-to-r from-blue-500 to-blue-600',
      hoverColor: 'hover:from-blue-600 hover:to-blue-700',
      glowColor: 'shadow-blue-500/20'
    },
    {
      label: 'Add New Task',
      onClick: () => addNotification('New task added!', 'info'),
      route: '/tasks',
      icon: (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
        </svg>
      ),
      color: 'bg-gradient-to-r from-green-500 to-emerald-600',
      hoverColor: 'hover:from-green-600 hover:to-emerald-700',
      glowColor: 'shadow-green-500/20'
    },
    {
      label: 'Start Pomodoro',
      onClick: () => addNotification('Setting 25 minute focus timer', 'info'),
      route: '/pomodoro',
      icon: (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      ),
      color: 'bg-gradient-to-r from-purple-500 to-indigo-600',
      hoverColor: 'hover:from-purple-600 hover:to-indigo-700',
      glowColor: 'shadow-purple-500/20'
    },
    {
      label: 'Get Insights',
      onClick: () => addNotification('Analyzing your study patterns...', 'info'),
      route: '/statistics',
      icon: (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
        </svg>
      ),
      color: 'bg-gradient-to-r from-amber-500 to-orange-600',
      hoverColor: 'hover:from-amber-600 hover:to-orange-700',
      glowColor: 'shadow-amber-500/20'
    }
  ], [addNotification]);

  // Set up keyboard shortcuts
  React.useEffect(() => {
    const handleKeyDown = (e) => {
      // Alt+S for Study
      if (e.altKey && e.key === 's') {
        buttons[0].onClick();
        if (buttons[0].route) {
          window.location.href = buttons[0].route;
        }
      }
      // Alt+P for Pomodoro
      if (e.altKey && e.key === 'p') {
        buttons[2].onClick();
        if (buttons[2].route) {
          window.location.href = buttons[2].route;
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [buttons]);

  return (
    <motion.div 
      className="mb-6 relative overflow-hidden"
      variants={itemVariants}
    >
      <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 to-purple-500/5 rounded-2xl"></div>
      <div className={`p-4 rounded-2xl ${theme.card} backdrop-blur-xl shadow-xl relative z-10 border border-gray-200 dark:border-gray-800 border-opacity-10`}
          style={{
            background: 'linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.05))'
          }}
      >
        <motion.h2 
          className={`text-lg font-semibold mb-4 ${theme.text.primary} bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500`}
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
        >
          Quick Actions
        </motion.h2>
        
        <div className="grid grid-cols-2 gap-3">
          {buttons.map((button, index) => (
            <ActionButton key={button.label} button={button} index={index} />
          ))}
        </div>
        
        {/* Interactive tip with enhanced styling */}
        <motion.div 
          className="mt-4 p-2 bg-blue-500/10 rounded-lg text-xs text-blue-700 dark:text-blue-300 flex items-center backdrop-blur-sm border border-blue-500/20"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1 text-blue-500" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2h-1V9a1 1 0 00-1-1z" clipRule="evenodd" />
          </svg>
          <span>Tip: Use <kbd className="px-1.5 py-0.5 bg-white/20 rounded mx-1 font-mono">Alt+S</kbd> for Study, <kbd className="px-1.5 py-0.5 bg-white/20 rounded mx-1 font-mono">Alt+P</kbd> for Pomodoro</span>
        </motion.div>
      </div>
    </motion.div>
  );
});

ActionPanel.displayName = 'ActionPanel';

export default ActionPanel; 