import React from 'react';
import DashboardContainer from '../components/dashboard/DashboardContainer';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';

/**
 * Dashboard Page Component
 * The main landing page of the application
 */
const Dashboard = () => {
  const { currentUser } = useAuth();
  
  // Get data from the authenticated user
  const studyData = currentUser && Array.isArray(currentUser.studyData) 
    ? currentUser.studyData 
    : [];
    
  const tasks = currentUser && Array.isArray(currentUser.tasks) 
    ? currentUser.tasks 
    : [];
  
  // Simple page transition variant
  const pageVariants = {
    initial: { opacity: 0 },
    animate: { opacity: 1, transition: { duration: 0.5 } },
    exit: { opacity: 0, transition: { duration: 0.3 } }
  };

  return (
    <motion.div 
      className="max-w-7xl mx-auto px-2"
      variants={pageVariants}
      initial="initial"
      animate="animate"
      exit="exit"
    >
      <DashboardContainer 
        studyData={studyData} 
        tasks={tasks}
      />
    </motion.div>
  );
};

export default Dashboard; 