import React from 'react';
import { motion } from 'framer-motion';
import { HiOutlineArrowSmRight } from 'react-icons/hi';

/**
 * A futuristic, glassmorphic stats card component with neural network animations
 */
const StatsCard = ({ 
  title = '', 
  value = '0', 
  change = 0, 
  icon, 
  id = '',
  theme = 'light', 
  color = 'blue',
  showMoreLink = false
}) => {
  // Handle positive or negative changes
  const isPositive = change >= 0;
  
  // Theme based styles
  const cardBg = theme === 'dark' ? 'bg-gray-800' : 'bg-white';
  const textColor = theme === 'dark' ? 'text-gray-200' : 'text-gray-800';
  const subTextColor = theme === 'dark' ? 'text-gray-400' : 'text-gray-500';
  
  // Color based styles for the icon
  const colorStyles = {
    blue: theme === 'dark' ? 'text-blue-400' : 'text-blue-500',
    green: theme === 'dark' ? 'text-green-400' : 'text-green-500',
    purple: theme === 'dark' ? 'text-purple-400' : 'text-purple-500',
    orange: theme === 'dark' ? 'text-orange-400' : 'text-orange-500'
  };

  // Enhanced color mapping for different card types
  const cardColors = {
    blue: {
      bg: 'from-blue-500/30 to-blue-600/20',
      border: 'border-blue-400/30',
      glow: 'rgba(59, 130, 246, 0.3)',
      icon: 'text-blue-400',
      accent: '#3B82F6'
    },
    green: {
      bg: 'from-green-500/30 to-green-600/20',
      border: 'border-green-400/30',
      glow: 'rgba(74, 222, 128, 0.3)',
      icon: 'text-green-400',
      accent: '#4ADE80'
    },
    purple: {
      bg: 'from-purple-500/30 to-purple-600/20',
      border: 'border-purple-400/30',
      glow: 'rgba(168, 85, 247, 0.3)',
      icon: 'text-purple-400',
      accent: '#A855F7'
    },
    cyan: {
      bg: 'from-cyan-500/30 to-cyan-600/20',
      border: 'border-cyan-400/30',
      glow: 'rgba(34, 211, 238, 0.3)',
      icon: 'text-cyan-400',
      accent: '#22D3EE'
    },
    neural: {
      bg: 'from-neural-400/30 to-neural-600/20',
      border: 'border-neural-400/30',
      glow: 'rgba(100, 200, 255, 0.3)',
      icon: 'text-neural-400',
      accent: '#64C8FF'
    }
  };

  const colorSet = cardColors[color] || cardColors.neural;
  
  // Neural network nodes
  const nodes = React.useMemo(() => {
    const nodeCount = 5;
    const nodeArray = [];
    
    for (let i = 0; i < nodeCount; i++) {
      nodeArray.push({
        x: 10 + Math.random() * 80,
        y: 10 + Math.random() * 80,
        size: 2 + Math.random() * 2,
        delay: Math.random() * 2
      });
    }
    
    return nodeArray;
  }, []);
  
  // Neural connections
  const connections = React.useMemo(() => {
    const connectionArray = [];
    
    // Create 3 connections between random nodes
    for (let i = 0; i < 3; i++) {
      const sourceIndex = Math.floor(Math.random() * nodes.length);
      let targetIndex;
      do {
        targetIndex = Math.floor(Math.random() * nodes.length);
      } while (targetIndex === sourceIndex);
      
      connectionArray.push({
        startX: nodes[sourceIndex].x,
        startY: nodes[sourceIndex].y,
        endX: nodes[targetIndex].x,
        endY: nodes[targetIndex].y,
        active: i === 0 // Make one connection active/highlighted
      });
    }
    
    return connectionArray;
  }, [nodes]);

  // Advanced card animation variants
  const cardVariants = {
    initial: { 
      opacity: 0,
      y: 20,
      scale: 0.95
    },
    animate: { 
      opacity: 1,
      y: 0,
      scale: 1,
      transition: {
        type: "spring",
        stiffness: 300,
        damping: 25,
        delay: 0.1
      }
    },
    hover: {
      scale: 1.03,
      boxShadow: "0 10px 20px rgba(0,0,0,0.19), 0 6px 6px rgba(0,0,0,0.23)",
      transition: {
        type: "spring",
        stiffness: 400,
        damping: 15
      }
    },
    tap: {
      scale: 0.98,
      boxShadow: "0 5px 10px rgba(0,0,0,0.15), 0 3px 3px rgba(0,0,0,0.1)",
      transition: {
        type: "spring",
        stiffness: 500,
        damping: 15
      }
    }
  };

  // Neural node animation
  const NeuralNode = ({ color, size = 3, x, y, delay = 0 }) => (
    <motion.div 
      className="absolute rounded-full"
      style={{
        backgroundColor: color,
        width: `${size}px`,
        height: `${size}px`,
        left: `${x}%`,
        top: `${y}%`,
        filter: 'blur(1px)'
      }}
      initial={{ opacity: 0 }}
      animate={{ 
        opacity: [0.2, 0.7, 0.2]
      }}
      transition={{
        duration: 2 + Math.random() * 2,
        repeat: Infinity,
        delay: delay
      }}
    />
  );

  // Neural connection line
  const NeuralConnection = ({ startX, startY, endX, endY, color, active = false }) => {
    // Calculate control points for curve
    const midX = (startX + endX) / 2;
    const midY = (startY + endY) / 2;
    const variance = (Math.random() - 0.5) * 20;
    
    const ctrlX = midX + variance;
    const ctrlY = midY + variance;
    
    // Path data for quadratic curve
    const pathData = `M ${startX} ${startY} Q ${ctrlX} ${ctrlY}, ${endX} ${endY}`;
    
    return (
      <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible">
        <path 
          d={pathData}
          stroke={color}
          strokeOpacity={active ? 0.4 : 0.15}
          strokeWidth={active ? 1 : 0.8}
          fill="none"
          strokeDasharray={active ? "none" : "3,3"}
          style={{
            filter: active ? `drop-shadow(0 0 2px ${color})` : 'none'
          }}
        />
        
        {active && (
          <motion.circle 
            r="2"
            fill={color}
            initial={{ opacity: 0 }}
            animate={{ 
              opacity: [0, 0.8, 0],
              pathOffset: [0, 1]
            }}
            transition={{ 
              duration: 2, 
              repeat: Infinity,
              ease: "linear",
              repeatDelay: 1
            }}
            style={{
              offsetPath: `path("${pathData}")`,
              offsetRotate: "0deg"
            }}
          />
        )}
      </svg>
    );
  };

  return (
    <motion.div
      className={`stats-card ${cardBg} backdrop-blur-xl rounded-xl border ${colorSet.border} p-4 relative overflow-hidden`}
      variants={cardVariants}
      initial="initial"
      animate="animate"
      whileHover="hover"
      whileTap="tap"
      style={{
        boxShadow: `0 4px 15px ${colorSet.glow}`,
      }}
    >
      {/* Glassmorphic background effect */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        {/* Base background */}
        <div className={`absolute inset-0 bg-gradient-to-br ${colorSet.bg} opacity-30`} />
        
        {/* Grid background */}
        <div 
          className="absolute inset-0 opacity-20"
          style={{ 
            backgroundImage: `linear-gradient(to right, ${colorSet.accent}20 1px, transparent 1px),
                             linear-gradient(to bottom, ${colorSet.accent}20 1px, transparent 1px)`,
            backgroundSize: '20px 20px'
          }} 
        />
        
        {/* Neural network nodes and connections */}
        <div className="absolute inset-0">
          {nodes.map((node, i) => (
            <NeuralNode 
              key={`node-${i}`}
              x={node.x}
              y={node.y}
              size={node.size}
              color={colorSet.accent}
              delay={node.delay}
            />
          ))}
          
          {connections.map((conn, i) => (
            <NeuralConnection 
              key={`conn-${i}`}
              startX={conn.startX}
              startY={conn.startY}
              endX={conn.endX}
              endY={conn.endY}
              color={colorSet.accent}
              active={conn.active}
            />
          ))}
        </div>
      </div>
      
      {/* Content */}
      <div className="relative z-10">
        {/* Icon */}
        <div className="flex justify-between mb-3 relative z-10">
          <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${colorStyles[color]} relative`}>
            <div className={`absolute inset-0 rounded-lg bg-gradient-to-br ${colorSet.bg} opacity-50`} />
            <div className="relative z-10">
              {icon}
            </div>
            
            {/* Animated glow effect */}
            <motion.div 
              className="absolute inset-0 rounded-lg"
              initial={{ opacity: 0.2 }}
              animate={{ opacity: [0.2, 0.4, 0.2] }}
              transition={{ duration: 2, repeat: Infinity }}
              style={{ 
                boxShadow: `0 0 10px ${colorSet.accent}`,
                background: `radial-gradient(circle at center, ${colorSet.accent}40 0%, transparent 70%)`
              }}
            />
          </div>
          
          {/* Change percentage indicator */}
          <div 
            className={`flex items-center text-sm font-medium ${
              isPositive ? 'text-green-400' : change < 0 ? 'text-red-400' : 'text-gray-400'
            }`}
          >
            <span>{isPositive ? '+' : ''}{change}%</span>
            <motion.div 
              className="w-4 h-4 flex items-center justify-center ml-1"
              initial={{ rotate: isPositive ? -45 : 45 }}
              animate={{ rotate: isPositive ? 0 : 90 }}
            >
              <HiOutlineArrowSmRight />
            </motion.div>
          </div>
        </div>
        
        {/* Title */}
        <div className={`text-sm font-medium mb-1 ${subTextColor}`}>{title}</div>
        
        {/* Value */}
        <div className={`text-2xl font-bold ${textColor}`}>{value}</div>
        
        {/* More link */}
        {showMoreLink && (
          <div className="mt-3 flex items-center text-sm">
            <button className={`${colorStyles[color]} font-medium flex items-center bg-transparent border-none p-0 cursor-pointer`}>
              More details
              <HiOutlineArrowSmRight className="ml-1" />
            </button>
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default StatsCard; 