import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

const PremiumLineGraph = ({ 
  data = [], 
  width = 600, 
  height = 300, 
  color = '#818cf8', // Default to indigo
  showDots = true,
  animate = true,
  strokeWidth = 3,
  title = 'Study Time Trend',
  yAxisLabel = 'Minutes',
  xAxisLabel = 'Days',
  showGlow = true,
}) => {
  const [pathLength, setPathLength] = useState(0);
  const [path, setPath] = useState('');
  const [areaPath, setAreaPath] = useState('');
  
  const margin = { top: 20, right: 30, bottom: 40, left: 50 };
  const graphWidth = width - margin.left - margin.right;
  const graphHeight = height - margin.top - margin.bottom;
  
  // Make sure we have at least 2 data points
  const safeData = data.length < 2 ? [{ day: 'Day 1', value: 0 }, { day: 'Day 2', value: 0 }] : data;
  
  useEffect(() => {
    if (safeData.length === 0) return;
    
    // Find min and max values
    const maxValue = Math.max(...safeData.map(d => d.value)) * 1.1 || 100; // 10% padding
    
    // Create scales
    const xScale = index => (index / (safeData.length - 1)) * graphWidth;
    const yScale = value => graphHeight - (value / maxValue) * graphHeight;
    
    // Generate path string for line
    let pathString = '';
    // Generate path string for area
    let areaPathString = '';
    
    safeData.forEach((item, index) => {
      const x = xScale(index);
      const y = yScale(item.value);
      
      if (index === 0) {
        pathString = `M ${x} ${y}`;
        areaPathString = `M ${x} ${graphHeight} L ${x} ${y}`;
      } else {
        // Use curved lines with bezier
        const prevX = xScale(index - 1);
        const prevY = yScale(safeData[index - 1].value);
        
        const cpX1 = prevX + (x - prevX) / 2;
        const cpX2 = prevX + (x - prevX) / 2;
        
        pathString += ` C ${cpX1} ${prevY}, ${cpX2} ${y}, ${x} ${y}`;
        areaPathString += ` C ${cpX1} ${prevY}, ${cpX2} ${y}, ${x} ${y}`;
      }
    });
    
    // Close the area path by adding bottom line
    const lastX = xScale(safeData.length - 1);
    areaPathString += ` L ${lastX} ${graphHeight} Z`;
    
    setPath(pathString);
    setAreaPath(areaPathString);
    
    // Reset pathLength for animation
    setPathLength(0);
    setTimeout(() => setPathLength(1), 100);
  }, [safeData, graphWidth, graphHeight]);
  
  return (
    <div className="relative w-full overflow-hidden rounded-xl">
      <svg width={width} height={height}>
        {/* Gradient definitions */}
        <defs>
          {/* Gradient for line */}
          <linearGradient id="lineGradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor={color} stopOpacity="0.6" />
            <stop offset="50%" stopColor={color} stopOpacity="1" />
            <stop offset="100%" stopColor={color} stopOpacity="0.6" />
          </linearGradient>
          
          {/* Gradient for area */}
          <linearGradient id="areaGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor={color} stopOpacity="0.5" />
            <stop offset="100%" stopColor={color} stopOpacity="0.05" />
          </linearGradient>
          
          {/* Glow filter */}
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="4" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Grid lines */}
          {[0, 0.25, 0.5, 0.75, 1].map((ratio, index) => {
            const y = graphHeight * ratio;
            
            return (
              <g key={`grid-${index}`}>
                <line 
                  x1={0} 
                  y1={y} 
                  x2={graphWidth} 
                  y2={y} 
                  stroke="currentColor" 
                  strokeOpacity="0.1" 
                  strokeDasharray="4 4" 
                />
              </g>
            );
          })}
          
          {/* Y-axis */}
          <line
            x1={0}
            y1={0}
            x2={0}
            y2={graphHeight}
            stroke="currentColor"
            strokeOpacity="0.2"
            strokeWidth={1}
          />
          
          {/* X-axis */}
          <line
            x1={0}
            y1={graphHeight}
            x2={graphWidth}
            y2={graphHeight}
            stroke="currentColor"
            strokeOpacity="0.2"
            strokeWidth={1}
          />
          
          {/* Area fill */}
          <motion.path
            d={areaPath}
            fill="url(#areaGradient)"
            initial={{ opacity: 0 }}
            animate={{ opacity: animate ? 1 : 0 }}
            transition={{ duration: 1, ease: "easeInOut" }}
          />
          
          {/* Path with optional glow */}
          <motion.path
            d={path}
            fill="none"
            stroke={showGlow ? "url(#lineGradient)" : color}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            filter={showGlow ? "url(#glow)" : "none"}
            initial={{ pathLength: 0 }}
            animate={{ pathLength: animate ? pathLength : 1 }}
            transition={{ duration: 2, ease: "easeInOut" }}
          />
          
          {/* Dots at data points with glow */}
          {showDots && safeData.map((item, index) => {
            const maxValue = Math.max(...safeData.map(d => d.value)) * 1.1 || 100;
            const x = (index / (safeData.length - 1)) * graphWidth;
            const y = graphHeight - (item.value / maxValue) * graphHeight;
            
            return (
              <g key={index} filter={showGlow ? "url(#glow)" : "none"}>
                <motion.circle
                  cx={x}
                  cy={y}
                  r={6}
                  fill="#fff"
                  strokeWidth={2}
                  stroke={color}
                  initial={{ opacity: 0, scale: 0 }}
                  animate={{ opacity: 1, scale: 1 }}
                  transition={{ 
                    delay: animate ? 1.5 + (index * 0.1) : 0,
                    duration: 0.2
                  }}
                />
                
                {/* Data point value tooltip */}
                <g className="point-value opacity-0 hover:opacity-100 transition-opacity duration-300">
                  <rect 
                    x={x - 25} 
                    y={y - 40} 
                    width="50" 
                    height="25" 
                    rx="5" 
                    fill={color}
                    fillOpacity="0.9"
                  />
                  <text 
                    x={x} 
                    y={y - 24} 
                    textAnchor="middle" 
                    fontSize="12" 
                    fontWeight="bold"
                    fill="white"
                  >
                    {(item.value / 60).toFixed(1)}h
                  </text>
                </g>
              </g>
            );
          })}
          
          {/* X-axis labels */}
          {safeData.map((item, index) => {
            const x = (index / (safeData.length - 1)) * graphWidth;
            
            return (
              <text
                key={`x-label-${index}`}
                x={x}
                y={graphHeight + 20}
                fontSize="12"
                textAnchor="middle"
                fill="currentColor"
                fillOpacity="0.7"
              >
                {item.day}
              </text>
            );
          })}
          
          {/* Y-axis labels */}
          {[0, 0.25, 0.5, 0.75, 1].map((ratio, index) => {
            const maxValue = Math.max(...safeData.map(d => d.value)) * 1.1 || 100;
            const value = Math.round(maxValue * (1 - ratio) / 60); // Convert to hours
            const y = graphHeight * ratio;
            
            return (
              <g key={`y-label-${index}`}>
                <text
                  x={-10}
                  y={y}
                  fontSize="12"
                  textAnchor="end"
                  alignmentBaseline="middle"
                  fill="currentColor"
                  fillOpacity="0.7"
                >
                  {value}h
                </text>
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
};

export default PremiumLineGraph; 