import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../../contexts/ThemeContext';
import { useNotification } from '../../components/NotificationContext';
import { useAuth } from '../../contexts/AuthContext';

// Premium Dashboard Components
import GreetingHeader from './GreetingHeader';
import StatsCard from './StatsCard';
import StatisticsPanel from './StatisticsPanel';
import ActionPanel from './ActionPanel';

// Page transition variants - simplified for better performance
const pageVariants = {
  initial: { 
    opacity: 0, 
    y: 20
  },
  animate: { 
    opacity: 1, 
    y: 0,
    transition: { 
      duration: 0.4,
      ease: "easeInOut",
      staggerChildren: 0.05
    }
  },
  exit: { 
    opacity: 0,
    y: -20,
    transition: { 
      duration: 0.25,
      ease: "easeInOut" 
    }
  }
};

// Shared item variants for staggered animations - simplified
const itemVariants = {
  initial: { opacity: 0, y: 20 },
  animate: { 
    opacity: 1, 
    y: 0,
    transition: { 
      duration: 0.3, 
      ease: "easeInOut" 
    }
  }
};

// Simplified neural connection for better performance
const NeuralConnection = ({ startPos, endPos, delay = 0 }) => (
  <svg className="absolute top-0 left-0 w-full h-full pointer-events-none z-0" style={{ overflow: 'visible' }}>
    <path 
      d={`M${startPos.x},${startPos.y} C${startPos.x + 100},${startPos.y} ${endPos.x - 100},${endPos.y} ${endPos.x},${endPos.y}`}
      stroke="rgba(100, 200, 255, 0.2)"
      strokeWidth="1"
      fill="none"
      strokeDasharray="5,5"
      style={{ opacity: 0.5 }}
    />
    
    <motion.circle
      r="3"
      fill="#80CFFF"
      initial={{ 
        opacity: 0,
        cx: startPos.x,
        cy: startPos.y
      }}
      animate={{ 
        opacity: [0, 0.7, 0],
        cx: [startPos.x, endPos.x],
        cy: [startPos.y, endPos.y]
      }}
      transition={{ 
        duration: 3, 
        delay,
        repeat: Infinity,
        repeatDelay: 5
      }}
    />
  </svg>
);

const DashboardContainer = (props) => {
  const { theme } = useTheme();
  const { addNotification } = useNotification();
  const { currentUser } = useAuth();
  
  // Handle undefined props or missing props entirely
  const { studyData = [], tasks = [] } = props || {};
  
  // Ensure we're working with arrays
  const safeStudyData = Array.isArray(studyData) ? studyData : [];
  const safeTasks = Array.isArray(tasks) ? tasks : [];
  
  const [currentTime, setCurrentTime] = useState(new Date());
  const [greeting, setGreeting] = useState('');
  const [totalStudyHours, setTotalStudyHours] = useState(0);
  const [completedTasksPercent, setCompletedTasksPercent] = useState(0);
  const [streakDays, setStreakDays] = useState(0);
  const [userName, setUserName] = useState('Student');
  const [connectionPoints, setConnectionPoints] = useState({
    timeCard: { x: 0, y: 0 },
    taskCard: { x: 0, y: 0 },
    streakCard: { x: 0, y: 0 },
    statsPanel: { x: 0, y: 0 },
    tasksPanel: { x: 0, y: 0 }
  });
  
  // Set user name from auth context
  useEffect(() => {
    if (currentUser && currentUser.name) {
      setUserName(currentUser.name);
    }
  }, [currentUser]);
  
  // Update time every minute
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 60000);
    
    // Initial time set and greeting update
    setCurrentTime(new Date());
    updateGreeting(new Date());
    
    // Calculate stats from props
    calculateStats();
    
    return () => {
      clearInterval(timer);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  
  // Update greeting based on time of day
  const updateGreeting = (time) => {
    const hours = time.getHours();
    let newGreeting = '';
    
    if (hours < 6) {
      newGreeting = "Good Night";
    } else if (hours < 12) {
      newGreeting = "Good Morning";
    } else if (hours < 17) {
      newGreeting = "Good Afternoon";
    } else if (hours < 22) {
      newGreeting = "Good Evening";
    } else {
      newGreeting = "Good Night";
    }
    
    setGreeting(newGreeting);
  };
  
  // Format time with custom futuristic format
  const getFormattedTime = () => {
    const hours = currentTime.getHours().toString().padStart(2, '0');
    const minutes = currentTime.getMinutes().toString().padStart(2, '0');
    return `${hours}:${minutes}`;
  };
  
  // Format date in more readable format
  const getFormattedDate = () => {
    const options = { weekday: 'long', month: 'long', day: 'numeric' };
    return currentTime.toLocaleDateString('en-US', options);
  };
  
  // Calculate stats from study data and tasks
  const calculateStats = () => {
    // Calculate completed tasks percentage
    if (safeTasks && safeTasks.length > 0) {
      const completed = safeTasks.filter(task => task.completed).length;
      setCompletedTasksPercent(Math.round((completed / safeTasks.length) * 100));
    }
    
    // Use the user's streakDays property or default to 0
    if (currentUser && typeof currentUser.streakDays === 'number') {
      setStreakDays(currentUser.streakDays);
    } else {
      setStreakDays(0); // Default to 0 instead of random
    }
    
    // Calculate total study hours from study data
    if (safeStudyData && safeStudyData.length > 0) {
      const total = safeStudyData.reduce((acc, day) => acc + day.value, 0);
      setTotalStudyHours(Math.round(total / 60)); // Convert minutes to hours
    }
  };
  
  // Calculate task status for notifications
  const getTaskStatus = () => {
    if (completedTasksPercent >= 80) return 'completed';
    if (completedTasksPercent >= 40) return 'inProgress';
    return 'pending';
  };
  
  // Icons for the stats cards
  const icons = {
    time: () => (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
    tasks: () => (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
    streak: () => (
      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
      </svg>
    )
  };
  
  // Update connection positions
    const updateConnectionPositions = () => {
    const getElementCenter = (id) => {
      const element = document.getElementById(id);
      if (!element) return null;
      
      const rect = element.getBoundingClientRect();
      return {
          x: rect.left + rect.width / 2,
          y: rect.top + rect.height / 2
        };
    };
    
    // Only create connections if elements exist
    let positions = {};
    
    // Stats cards centers
    const timeCard = getElementCenter('stats-card-0');
    const taskCard = getElementCenter('stats-card-1');
    const streakCard = getElementCenter('stats-card-2');
    
    // Panel centers
    const statsPanel = getElementCenter('statistics-panel');
    const tasksPanel = getElementCenter('action-panel');
    
    if (timeCard && taskCard && streakCard && statsPanel && tasksPanel) {
      positions = {
        'stats-card-0': timeCard,
        'stats-card-1': taskCard, 
        'stats-card-2': streakCard,
        'statistics-panel': statsPanel,
        'action-panel': tasksPanel
      };
      
      setConnectionPoints(positions);
    }
  };
  
  // Handle window resize with useCallback to avoid dependency loops
  const handleResize = useCallback(() => {
    updateConnectionPositions();
  }, []);
  
  // Only update connection positions when dashboard elements are rendered
  useEffect(() => {
    // Wait for elements to be rendered
    setTimeout(() => {
      updateConnectionPositions();
      
      // Update on window resize
    window.addEventListener('resize', handleResize);
    }, 500);
    
    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, [handleResize]);
  
  return (
    <motion.div 
      className="max-w-7xl mx-auto px-2 pb-24 relative"
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
    >
      {/* Neural connections between dashboard elements - simplified for better performance */}
      {Object.keys(connectionPoints).length > 0 && (
        <div className="fixed inset-0 pointer-events-none z-0">
          {/* Connect stats panel to action panel */}
          {connectionPoints['statistics-panel'] && connectionPoints['action-panel'] && (
            <NeuralConnection 
              key="connection-panels"
              startPos={connectionPoints['statistics-panel']}
              endPos={connectionPoints['action-panel']}
              delay={0.5}
            />
          )}
        </div>
      )}
      
      {/* Greeting Header with time display */}
      <GreetingHeader 
        userName={userName}
        greeting={greeting}
        formattedDate={getFormattedDate()}
        formattedTime={getFormattedTime()}
        theme={theme}
      />
      
      {/* Stats Overview with premium cards */}
      <motion.div 
        className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6"
        variants={itemVariants}
      >
        <div className="stats-card" id="stats-card-0">
          <StatsCard 
            title="Total Study Time"
            value={`${totalStudyHours} hours`}
            change={5.2}
            icon={icons.time()}
            color="blue"
          />
        </div>
        
        <div className="stats-card" id="stats-card-1">
          <StatsCard 
            title="Tasks Completed"
            value={`${safeTasks.filter(task => task.completed).length}/${safeTasks.length}`}
            change={completedTasksPercent > 50 ? 8.3 : -3.1}
            icon={icons.tasks()}
            color="green"
          />
        </div>
        
        <div className="stats-card" id="stats-card-2">
          <StatsCard 
            title="Study Streak"
            value={`${streakDays} days`}
            change={2.5}
            icon={icons.streak()}
            color="purple"
          />
        </div>
      </motion.div>
      
      {/* Statistics Panel */}
      <motion.div
        id="statistics-panel"
        className="glass-panel rounded-xl mb-6 overflow-hidden border border-neural-400/10 shadow-neural"
        variants={itemVariants}
      >
        <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-neural-400/20 to-transparent" />
        
        <div className="p-4">
          <StatisticsPanel 
            studyData={safeStudyData} 
            completionPercentage={completedTasksPercent}
            status={getTaskStatus()}
            theme={theme}
          />
        </div>
      </motion.div>
      
      {/* Action Items Panel */}
      <motion.div
        id="action-panel"
        className="glass-panel rounded-xl overflow-hidden border border-neural-400/10 shadow-neural"
        variants={itemVariants}
      >
        <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-neural-400/20 to-transparent" />
        
        <div className="p-4">
          <ActionPanel 
            tasks={safeTasks.filter(task => !task.completed).slice(0, 5)}
            theme={theme}
            addNotification={addNotification}
            itemVariants={itemVariants}
          />
        </div>
      </motion.div>
    </motion.div>
  );
};

export default DashboardContainer; 