import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

const PremiumCircularProgressBar = ({ 
  progress = 0, 
  status = 'pending',
  size = 200,
  strokeWidth = 12,
  animationDuration = 1.5,
  title = ''
}) => {
  const [progressValue, setProgressValue] = useState(0);
  
  // Define status colors with gradients
  const statusColors = {
    pending: {
      start: '#3B82F6', // Blue
      end: '#2563EB',
      glow: 'rgba(59, 130, 246, 0.5)',
      text: 'text-blue-500'
    },
    inProgress: {
      start: '#8B5CF6', // Purple
      end: '#7C3AED',
      glow: 'rgba(139, 92, 246, 0.5)',
      text: 'text-purple-500'
    },
    completed: {
      start: '#10B981', // Green
      end: '#059669',
      glow: 'rgba(16, 185, 129, 0.5)',
      text: 'text-emerald-500'
    }
  };
  
  const currentColor = statusColors[status] || statusColors.pending;
  
  // Circle properties
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = size / 2;
  
  // Animation to fill the circle
  useEffect(() => {
    // Start from 0 and animate to actual progress
    setProgressValue(0);
    
    const timer = setTimeout(() => {
      setProgressValue(progress);
    }, 100);
    
    return () => clearTimeout(timer);
  }, [progress]);
  
  // Calculate stroke dash offset based on progress
  const strokeDashoffset = circumference - (progressValue / 100) * circumference;
  
  return (
    <div className="relative" style={{ width: size, height: size }}>
      {/* Background glow effect */}
      <div 
        className="absolute inset-0 blur-xl opacity-20 rounded-full" 
        style={{ 
          background: `radial-gradient(circle, ${currentColor.glow} 0%, rgba(0,0,0,0) 70%)`,
        }}
      />
      
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        {/* Gradient definitions */}
        <defs>
          <linearGradient id={`circleGradient-${status}`} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={currentColor.start} />
            <stop offset="100%" stopColor={currentColor.end} />
          </linearGradient>
          
          <filter id="circleGlow">
            <feGaussianBlur stdDeviation="3.5" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>
        
        {/* Background circle */}
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="transparent"
          stroke="currentColor"
          strokeOpacity="0.1"
          strokeWidth={strokeWidth}
        />
        
        {/* Progress circle with gradient and glow */}
        <motion.circle
          cx={center}
          cy={center}
          r={radius}
          fill="transparent"
          stroke={`url(#circleGradient-${status})`}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          filter="url(#circleGlow)"
          initial={{ strokeDashoffset: circumference }}
          animate={{ strokeDashoffset }}
          transition={{ duration: animationDuration, ease: "easeInOut" }}
          transform={`rotate(-90 ${center} ${center})`}
        />
        
        {/* Percentage text */}
        <text
          x={center}
          y={center}
          textAnchor="middle"
          dominantBaseline="middle"
          className={`text-3xl font-bold ${currentColor.text}`}
          filter="url(#circleGlow)"
        >
          {Math.round(progressValue)}%
        </text>
        
        {/* Title text */}
        {title && (
          <text
            x={center}
            y={center + 25}
            textAnchor="middle"
            dominantBaseline="middle"
            className="text-sm text-gray-500 dark:text-gray-400"
          >
            {title}
          </text>
        )}
      </svg>
      
      {/* Animated embellishment - floating dots */}
      <div className="absolute inset-0 pointer-events-none">
        {[...Array(5)].map((_, i) => (
          <motion.div
            key={i}
            className="absolute rounded-full"
            style={{ 
              width: 6, 
              height: 6, 
              backgroundColor: currentColor.start,
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              opacity: 0.6
            }}
            animate={{ 
              y: [0, -10, 0], 
              opacity: [0.6, 0.9, 0.6],
              scale: [1, 1.2, 1],
            }}
            transition={{ 
              duration: 3 + i, 
              repeat: Infinity,
              repeatType: "reverse",
              delay: i * 0.5
            }}
          />
        ))}
      </div>
    </div>
  );
};

export default PremiumCircularProgressBar; 